'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Save, ArrowLeft, Plus } from 'lucide-react';
import Link from 'next/link';
import { Lesson, LessonStep, StepType } from '@/types/lesson';
import { StepBuilder } from '../components/StepBuilder';

const generateId = () => Math.random().toString(36).substr(2, 9);

export default function CreateLessonPage() {
  const router = useRouter();
  const [isSaving, setIsSaving] = useState(false);
  const [lesson, setLesson] = useState<Partial<Lesson>>({
    id: generateId(),
    status: 'locked',
    steps: []
  });

  const addStep = (type: StepType) => {
    const newStep: LessonStep = {
      id: generateId(),
      type,
      title: '',
      data: {} as any
    };
    setLesson(prev => ({ ...prev, steps: [...(prev.steps || []), newStep] }));
  };

  const updateStep = (index: number, updatedStep: LessonStep) => {
    const newSteps = [...(lesson.steps || [])];
    newSteps[index] = updatedStep;
    setLesson({ ...lesson, steps: newSteps });
  };

  const removeStep = (index: number) => {
    const newSteps = (lesson.steps || []).filter((_, i) => i !== index);
    setLesson({ ...lesson, steps: newSteps });
  };

  const handleSave = async () => {
    if (!lesson.title || !lesson.slug || !lesson.module) {
      alert('Preencha pelo menos Título, Slug e Módulo da lição.');
      return;
    }

    setIsSaving(true);
    try {
      const response = await fetch('/api/admin/content', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'lessons',
          id: lesson.slug,
          data: lesson
        })
      });

      if (!response.ok) throw new Error('Falha ao salvar a lição');
      
      alert('Lição salva com sucesso no repositório!');
      router.push('/admin/lessons');
    } catch (error) {
      console.error(error);
      alert('Erro ao salvar a lição');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-32">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" asChild className="text-muted-foreground hover:text-foreground">
            <Link href="/admin/lessons"><ArrowLeft className="w-5 h-5" /></Link>
          </Button>
          <h1 className="text-3xl font-bold font-headline text-foreground">Nova Lição</h1>
        </div>
        <Button 
          onClick={handleSave} 
          disabled={isSaving}
          className="bg-brand-gold text-brand-black hover:bg-brand-gold/90 font-bold px-8 h-12"
        >
          <Save className="w-5 h-5 mr-2" />
          {isSaving ? 'Salvando...' : 'Salvar Lição'}
        </Button>
      </div>

      <div className="bg-card border border-border rounded-2xl p-6 md:p-8 space-y-6">
        <h2 className="text-xl font-bold font-headline mb-4 text-brand-gold border-b border-border pb-2">Configurações Gerais</h2>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-bold text-muted-foreground mb-1">Título da Lição</label>
            <Input 
              value={lesson.title || ''} 
              onChange={(e) => setLesson({...lesson, title: e.target.value})}
              placeholder="Ex: Qualidades do Som"
            />
          </div>
          <div>
            <label className="block text-sm font-bold text-muted-foreground mb-1">Slug (Identificador URL)</label>
            <Input 
              value={lesson.slug || ''} 
              onChange={(e) => setLesson({...lesson, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '-')})}
              placeholder="ex: qualidades-do-som"
              className="font-mono text-sm"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-sm font-bold text-muted-foreground mb-1">Módulo Pai (Número)</label>
            <Input 
              type="number"
              value={lesson.module || ''} 
              onChange={(e) => setLesson({...lesson, module: parseInt(e.target.value)})}
              placeholder="Ex: 1"
            />
          </div>
          <div>
            <label className="block text-sm font-bold text-muted-foreground mb-1">Status Inicial</label>
            <select 
              className="flex h-10 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
              value={lesson.status || 'locked'}
              onChange={(e) => setLesson({...lesson, status: e.target.value as any})}
            >
              <option value="locked">Bloqueada</option>
              <option value="available">Disponível</option>
              <option value="completed">Concluída (Debug)</option>
            </select>
          </div>
        </div>

        <div>
          <label className="block text-sm font-bold text-muted-foreground mb-1">Descrição Curta</label>
          <Textarea 
            value={lesson.description || ''} 
            onChange={(e) => setLesson({...lesson, description: e.target.value})}
            placeholder="Aparece no card da lição..."
            className="h-20"
          />
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex items-center justify-between border-b border-border pb-4">
          <h2 className="text-2xl font-bold font-headline text-foreground">Passos da Lição (Slides)</h2>
        </div>

        {lesson.steps?.map((step, index) => (
          <StepBuilder 
            key={step.id} 
            step={step} 
            index={index} 
            onChange={(updated) => updateStep(index, updated)}
            onRemove={() => removeStep(index)}
          />
        ))}

        {(!lesson.steps || lesson.steps.length === 0) && (
          <div className="text-center py-12 border-2 border-dashed border-border rounded-2xl bg-card">
            <p className="text-muted-foreground mb-4">Esta lição ainda não possui nenhum passo ou desafio.</p>
          </div>
        )}

        <div className="grid grid-cols-2 md:grid-cols-3 gap-3 pt-6 border-t border-border">
          <Button variant="outline" onClick={() => addStep('theory')} className="border-brand-gold text-brand-gold hover:bg-brand-gold/10">
            <Plus className="w-4 h-4 mr-2" /> Teoria
          </Button>
          <Button variant="outline" onClick={() => addStep('quiz')} className="border-blue-500 text-blue-500 hover:bg-blue-500/10">
            <Plus className="w-4 h-4 mr-2" /> Múltipla Escolha
          </Button>
          <Button variant="outline" onClick={() => addStep('true_false')} className="border-purple-500 text-purple-500 hover:bg-purple-500/10">
            <Plus className="w-4 h-4 mr-2" /> Verdadeiro / Falso
          </Button>
          <Button variant="outline" onClick={() => addStep('match_columns')} className="border-green-500 text-green-500 hover:bg-green-500/10">
            <Plus className="w-4 h-4 mr-2" /> Colunas
          </Button>
          <Button variant="outline" onClick={() => addStep('memory_game')} className="border-orange-500 text-orange-500 hover:bg-orange-500/10">
            <Plus className="w-4 h-4 mr-2" /> Memória
          </Button>
          <Button variant="outline" onClick={() => addStep('fill_blanks')} className="border-pink-500 text-pink-500 hover:bg-pink-500/10">
            <Plus className="w-4 h-4 mr-2" /> Lacunas
          </Button>
        </div>
      </div>
    </div>
  );
}

import { NextResponse } from 'next/server';
import { DATABASE } from '@/constants/curriculum';
import fs from 'fs/promises';
import path from 'path';
import { Lesson } from '@/types/lesson';
import { Trail } from '@/types/curriculum';

export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    // 1. Clonar o DATABASE estático para não mutar a constante original
    const dynamicDb: Trail[] = JSON.parse(JSON.stringify(DATABASE));
    
    // 2. Ler todos os arquivos JSON da pasta de lições
    const contentDir = path.join(process.cwd(), 'src', 'content', 'lessons');
    let jsonFiles: string[] = [];
    
    try {
      const files = await fs.readdir(contentDir);
      jsonFiles = files.filter(f => f.endsWith('.json'));
    } catch (_e) {
      // Pasta pode não existir ainda no primeiro run
    }

    const dynamicLessons: Lesson[] = [];

    for (const file of jsonFiles) {
      try {
        const content = await fs.readFile(path.join(contentDir, file), 'utf-8');
        const lesson: Lesson = JSON.parse(content);
        dynamicLessons.push(lesson);
      } catch (err) {
        console.error('Erro ao ler lição JSON:', file, err);
      }
    }

    // 3. Mesclar as lições dinâmicas na estrutura do DATABASE
    // Regra: Se o slug ou ID bater com uma lição existente, substitui o conteúdo dela.
    // Se não bater com nenhuma, adiciona na trilha "Cursos Livres" (livres).
    
    const unmappedLessons: Lesson[] = [];

    for (const dLesson of dynamicLessons) {
      let found = false;
      
      for (const trail of dynamicDb) {
        for (const course of trail.courses) {
          for (const module of course.modules) {
            const index = module.lessons.findIndex((l: Lesson) => l.id === dLesson.id || l.slug === dLesson.slug);
            if (index !== -1) {
              // Mescla os dados (mantém a estrutura mas atualiza steps, título, descrição)
              module.lessons[index] = {
                ...module.lessons[index],
                title: dLesson.title || module.lessons[index].title,
                description: dLesson.description || module.lessons[index].description,
                status: dLesson.status || module.lessons[index].status,
                steps: dLesson.steps || []
              };
              found = true;
            }
          }
        }
      }

      if (!found) {
        unmappedLessons.push(dLesson);
      }
    }

    // 4. Se houver lições não mapeadas (novas criadas no Admin), adiciona aos Cursos Livres
    if (unmappedLessons.length > 0) {
      const livresTrail = dynamicDb.find(t => t.id === 'livres');
      if (livresTrail) {
        if (livresTrail.courses.length === 0) {
          livresTrail.courses.push({
            id: 'curso-livre-geral',
            title: 'Aulas Avulsas',
            description: 'Aulas e desafios criados pela comunidade e professores.',
            icon: 'BookOpen',
            modules: [
              {
                id: 'mod-livre-1',
                title: 'Conteúdo Dinâmico',
                description: 'Lições adicionadas recentemente.',
                author: 'Vários Autores',
                lessons: []
              }
            ]
          });
        }
        
        // Adiciona as lições órfãs no primeiro módulo do primeiro curso livre
        livresTrail.courses[0].modules[0].lessons.push(...unmappedLessons);
      }
    }

    return NextResponse.json({ database: dynamicDb });
  } // eslint-disable-next-line @typescript-eslint/no-explicit-any
    catch (error: any) {
    console.error('Erro na API de curriculum:', error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

'use client';

import { useEffect, useState, Suspense, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { useUser } from '@/contexts/UserContext';
import { auth, db } from '@/lib/firebase';
import { updatePassword } from 'firebase/auth';
import { doc, updateDoc } from 'firebase/firestore';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Logo } from '@/components/logo';

function FinishSignupContent() {
  const { finishMagicLinkSignup, user } = useUser();
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [status, setStatus] = useState<'verifying' | 'ask_email' | 'setup_profile' | 'done' | 'error'>('verifying');
  const [errorMsg, setErrorMsg] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const isVerifyingRef = useRef(false);

  useEffect(() => {
    if (status !== 'verifying') return;
    if (isVerifyingRef.current) return;
    isVerifyingRef.current = true;
    
    // Na primeira renderização (no client), tenta pegar o email do LocalStorage
    const savedEmail = window.localStorage.getItem('emailForSignIn');
    if (!savedEmail) {
      // Se abriu a guia anonimamente ou em outro device, pedimos o email.
      setStatus('ask_email');
      return;
    }

    handleLinkVerification(savedEmail);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status]);

  const handleLinkVerification = async (emailToVerify: string) => {
    try {
      // Tenta validar o link
      await finishMagicLinkSignup(emailToVerify, window.location.href);
      setStatus('setup_profile');
    } catch (error: any | unknown) {
      console.error(error);
      setStatus('error');
      setErrorMsg(error.message || 'Link inválido ou expirado.');
    }
  };

  const submitEmail = () => {
    if (!email) return;
    setStatus('verifying');
    handleLinkVerification(email);
  };

  const handleSetupSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !password) return;
    
    setIsSubmitting(true);
    try {
      if (!auth.currentUser) throw new Error('Usuário não autenticado.');
      
      // Define a senha para login futuro com Email/Senha
      await updatePassword(auth.currentUser, password);
      
      // Atualiza o username no Firestore
      if (user?.uid) {
        const userRef = doc(db, 'users', user.uid);
        await updateDoc(userRef, { username });
      }
      
      setStatus('done');
      setTimeout(() => {
        // Envia pro fluxo de onboarding ou dashboard
        router.push('/dashboard'); 
      }, 1500);
      
    } catch (error: any | unknown) {
      console.error(error);
      setErrorMsg(error.message || 'Erro ao concluir perfil.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-black flex flex-col items-center pt-24 px-4 text-white">
      <div className="mb-8">
        <Logo className="h-12 w-auto" />
      </div>
      
      <Card className="w-full max-w-md bg-zinc-900 border-zinc-800">
        <CardHeader>
          <CardTitle className="text-2xl font-bold">Completar Cadastro</CardTitle>
          <CardDescription className="text-zinc-400">
            {status === 'verifying' && 'Verificando seu link seguro...'}
            {status === 'ask_email' && 'Por favor, confirme o e-mail que usou para se cadastrar.'}
            {status === 'setup_profile' && 'Link validado! Agora escolha seu username e crie sua senha definitiva.'}
            {status === 'done' && 'Perfil concluído!'}
            {status === 'error' && 'Ops, ocorreu um erro.'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {status === 'verifying' && (
            <div className="flex justify-center py-8">
              <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-primary"></div>
            </div>
          )}

          {status === 'ask_email' && (
            <div className="space-y-4">
              <div>
                <label className="text-sm font-medium text-zinc-400">E-mail</label>
                <Input 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="seu@email.com"
                  className="bg-zinc-950 border-zinc-800 mt-1"
                />
              </div>
              <Button onClick={submitEmail} className="w-full font-bold bg-primary text-black hover:bg-primary/90">
                Confirmar
              </Button>
            </div>
          )}

          {status === 'setup_profile' && (
            <form onSubmit={handleSetupSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-medium text-zinc-400">Nome de Usuário (Username)</label>
                <Input 
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="ex: johndoe"
                  className="bg-zinc-950 border-zinc-800 mt-1"
                  required
                />
              </div>
              <div>
                <label className="text-sm font-medium text-zinc-400">Criar Senha de Acesso</label>
                <Input 
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Mínimo 6 caracteres"
                  className="bg-zinc-950 border-zinc-800 mt-1"
                  required
                  minLength={6}
                />
              </div>
              
              {errorMsg && <p className="text-red-500 text-sm">{errorMsg}</p>}

              <Button type="submit" disabled={isSubmitting} className="w-full font-bold bg-primary text-black hover:bg-primary/90">
                {isSubmitting ? 'Salvando...' : 'Concluir e Entrar'}
              </Button>
            </form>
          )}

          {status === 'done' && (
            <div className="flex flex-col items-center py-6">
              <div className="w-12 h-12 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mb-4">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <p className="text-center font-medium">Tudo pronto! Redirecionando...</p>
            </div>
          )}

          {status === 'error' && (
            <div className="text-center py-6 space-y-4">
              <p className="text-red-400 font-medium">{errorMsg}</p>
              <Button variant="outline" onClick={() => router.push('/')} className="border-zinc-800 text-white">
                Voltar para a Home
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default function FinishSignup() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-black" />}>
      <FinishSignupContent />
    </Suspense>
  );
}

import { getBlogPosts, getBlogPost } from '@/utils/content';
import { notFound } from 'next/navigation';
import Link from 'next/link';
import { Logo } from '@/components/logo';
import { ArrowLeft, Calendar, User } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { PublicHeader } from '@/components/public-header';
import { PublicFooter } from '@/components/public-footer';
import ReactMarkdown from 'react-markdown';
import { AuthorFooter } from '@/components/author-footer';
import { BlogComments } from '@/modules/blog/components/BlogComments';

interface Props {
  params: Promise<{
    slug: string;
  }>;
}

export async function generateMetadata({ params }: Props) {
  const { slug } = await params;
  const post = await getBlogPost(slug);
  if (!post) return { title: 'Artigo não encontrado | Nota Dentro' };

  return {
    title: `${post.title} | Artigos Nota Dentro`,
    description: post.excerpt,
  };
}

// Isso permite que o Next.js gere as páginas estáticas durante o build (Otimização Máxima de SEO)
export async function generateStaticParams() {
  const posts = await getBlogPosts();
  return posts.map((post) => ({
    slug: post.slug,
  }));
}

export default async function BlogPostPage({ params }: Props) {
  const { slug } = await params;
  const post = await getBlogPost(slug);

  if (!post) {
    notFound();
  }

  return (
    <div className="min-h-screen flex flex-col bg-background">
      <PublicHeader />

      <main className="flex-1 container mx-auto px-4 pt-32 pb-12 md:pt-40 md:pb-16 max-w-3xl">
        <Button variant="ghost" asChild className="mb-8 -ml-4 text-muted-foreground hover:text-foreground">
          <Link href="/blog">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Voltar para Artigos
          </Link>
        </Button>

        <article className="max-w-none">
          <h1 className="text-4xl md:text-5xl font-bold font-headline mb-4">{post.title}</h1>
          {post.subtitle && (
            <p className="text-xl text-muted-foreground mb-8 font-body leading-relaxed">
              {post.subtitle}
            </p>
          )}

          <div className="flex items-center gap-6 text-sm text-muted-foreground mb-8 pb-8 border-b">
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              <span>{new Date(post.date).toLocaleDateString('pt-BR')}</span>
            </div>
            <div className="flex items-center gap-2">
              <User className="w-4 h-4" />
              <span>{post.author}</span>
            </div>
          </div>

          <div className="prose prose-lg dark:prose-invert prose-brand max-w-none font-body">
            <ReactMarkdown>
              {post.content}
            </ReactMarkdown>
          </div>
          
          <AuthorFooter />
          <BlogComments slug={slug} />
        </article>
      </main>

      <PublicFooter />
    </div>
  );
}

import Link from 'next/link';
import { getBlogPosts } from '@/utils/content';
import { Logo } from '@/components/logo';
import { ArrowRight, Calendar, User } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { PublicHeader } from '@/components/public-header';
import { PublicFooter } from '@/components/public-footer';

export const metadata = {
  title: 'Artigos | Nota Dentro',
  description: 'Artigos, tutoriais e dicas sobre teoria musical, harmonia, ritmo e muito mais.',
};

export default async function BlogListPage() {
  const posts = await getBlogPosts();

  return (
    <div className="min-h-screen flex flex-col bg-background">
      <PublicHeader />

      <main className="flex-1 container mx-auto px-4 pt-32 pb-12 md:pt-40 md:pb-16 max-w-5xl">
        <div className="mb-12 space-y-4">
          <h1 className="text-4xl md:text-5xl font-bold font-headline">Artigos Nota Dentro</h1>
          <p className="text-xl text-muted-foreground">Dicas, tutoriais e teoria musical na prática.</p>
        </div>

        <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
          {posts.map((post) => (
            <Link key={post.id} href={`/blog/${post.slug}`} className="group flex flex-col h-full bg-card rounded-2xl border hover:border-primary transition-colors overflow-hidden hover:shadow-lg">
              <div className="p-6 flex flex-col flex-1">
                <h2 className="text-2xl font-bold font-headline mb-3 group-hover:text-primary transition-colors line-clamp-2">
                  {post.title}
                </h2>
                <p className="text-muted-foreground mb-6 line-clamp-3 flex-1">
                  {post.excerpt}
                </p>
                
                <div className="flex items-center justify-between mt-auto pt-4 border-t text-sm text-muted-foreground">
                  <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4" />
                    <span>{new Date(post.date).toLocaleDateString('pt-BR')}</span>
                  </div>
                  <div className="flex items-center text-primary font-bold">
                    <span>Ler mais</span>
                    <ArrowRight className="w-4 h-4 ml-1 group-hover:translate-x-1 transition-transform" />
                  </div>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </main>

      <PublicFooter />
    </div>
  );
}

import React from 'react';
import { notFound } from 'next/navigation';
import { getDynamicCurriculum } from '@/utils/content';
import { ArrowLeft } from 'lucide-react';
import Link from 'next/link';
import { CourseMapWrapper } from '@/modules/dashboard/components/CourseMapWrapper';

export default async function CoursePage({ params }: { params: Promise<{ courseId: string }> }) {
  const resolvedParams = await params;
  const dynamicDb = await getDynamicCurriculum();
  let foundCourse = null;
  let trailId = '';

  for (const trail of dynamicDb) {
    const course = trail.courses.find((c: any) => c.id === resolvedParams.courseId);
    if (course) {
      foundCourse = course;
      trailId = trail.id;
      break;
    }
  }

  if (!foundCourse) notFound();

  return (
    <div className="p-4 md:p-8 min-h-[calc(100vh-4rem)] font-body">
      <div className="max-w-4xl mx-auto">
        <Link href={`/dashboard/trail/${trailId}`} className="inline-flex items-center text-brand-gray hover:text-[#2D8A5C] font-bold mb-8 transition-colors">
          <ArrowLeft className="w-5 h-5 mr-2" /> Voltar para Cursos
        </Link>
        
        <header className="mb-12">
          <h1 className="text-4xl font-bold font-headline text-foreground">{foundCourse.title}</h1>
          <p className="text-muted-foreground text-xl mt-2">{foundCourse.description}</p>
        </header>

        <CourseMapWrapper course={foundCourse} />
      </div>
    </div>
  );
}

