'use client';

import { useParams, useRouter } from 'next/navigation';
import { useState, useEffect } from 'react';
import { LessonEngine } from '@/modules/lesson/components/LessonEngine';
import { Button } from '@/components/ui/button';
import { useGamification } from '@/context/GamificationContext';
import { Trail } from '@/types/curriculum';

export default function LessonPage() {
    const params = useParams();
    const router = useRouter();
    const courseId = params.courseId as string;
    const lessonId = params.lessonId as string;
    const { isHydrated } = useGamification();

    const [database, setDatabase] = useState<Trail[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
      fetch('/api/public/curriculum', { cache: 'no-store' })
        .then(res => res.json())
        .then(data => {
          if (data.database) {
            setDatabase(data.database);
          }
          setIsLoading(false);
        })
        .catch(() => setIsLoading(false));
    }, []);

    let foundLesson = null;
    let nextLessonId: string | undefined = undefined;

    if (!isLoading && database.length > 0) {
      for (const trail of database) {
        for (const course of trail.courses) {
          if (course.id === courseId) {
            for (let mIndex = 0; mIndex < course.modules.length; mIndex++) {
              const module = course.modules[mIndex];
              const lessonIndex = module.lessons.findIndex((l: any) => l.id === lessonId || l.slug === lessonId);
              
              if (lessonIndex !== -1) {
                foundLesson = module.lessons[lessonIndex];
                if (lessonIndex < module.lessons.length - 1) {
                  nextLessonId = module.lessons[lessonIndex + 1].id;
                } else if (mIndex < course.modules.length - 1) {
                  nextLessonId = course.modules[mIndex + 1].lessons[0]?.id;
                }
                break;
              }
            }
          }
          if (foundLesson) break;
        }
        if (foundLesson) break;
      }
    }

    if (!isHydrated || isLoading) {
      return (
        <div className="flex-1 flex flex-col items-center justify-center min-h-screen bg-background">
          <div className="w-12 h-12 border-4 border-brand-gold border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-brand-gray font-bold">Carregando sala de aula...</p>
        </div>
      );
    }

    if (!foundLesson) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center min-h-screen bg-background">
                <h1 className="text-2xl font-bold font-headline text-brand-black dark:text-brand-white">Lição não encontrada</h1>
                <Button onClick={() => router.push('/dashboard')} className="mt-4 bg-[#2D8A5C] text-white hover:bg-green-600 rounded-2xl py-6 px-8 font-bold">
                    Voltar ao Dashboard
                </Button>
            </div>
        );
    }

    return (
        <LessonEngine 
          lesson={foundLesson} 
          nextLessonId={nextLessonId}
          onClose={() => router.push(`/dashboard/course/${courseId}`)} 
        />
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useUser } from '@/contexts/UserContext';
import { db } from '@/lib/firebase';
import { doc, updateDoc } from 'firebase/firestore';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Logo } from '@/components/logo';

export default function ProfileSetup() {
  const { user, isUserLoading } = useUser();
  const router = useRouter();
  const [username, setUsername] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Se o usuário ainda tá carregando, aguarda
  // Se não tem usuário logado depois do load, manda pra Home
  useEffect(() => {
    if (!isUserLoading && !user) {
      router.push('/');
    }
  }, [isUserLoading, user, router]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username || !user?.uid) return;
    
    setIsSubmitting(true);
    try {
      const userRef = doc(db, 'users', user.uid);
      await updateDoc(userRef, { username });
      // Redireciona para o dashboard ou onboarding musical
      router.push('/dashboard');
    } catch (error: any) {
      console.error(error);
      setErrorMsg(error.message || 'Erro ao salvar o nome de usuário.');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (isUserLoading || !user) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black flex flex-col items-center pt-24 px-4 text-white">
      <div className="mb-8">
        <Logo className="h-12 w-auto" />
      </div>
      
      <Card className="w-full max-w-md bg-zinc-900 border-zinc-800">
        <CardHeader>
          <CardTitle className="text-2xl font-bold">Quase lá!</CardTitle>
          <CardDescription className="text-zinc-400">
            Bem-vindo, {user.name}! Escolha como você quer ser chamado na plataforma.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-sm font-medium text-zinc-400">Nome de Usuário (Username)</label>
              <Input 
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder="ex: johndoe"
                className="bg-zinc-950 border-zinc-800 mt-1 focus-visible:ring-primary"
                required
              />
            </div>
            
            {errorMsg && <p className="text-red-500 text-sm">{errorMsg}</p>}

            <Button type="submit" disabled={isSubmitting} className="w-full font-bold bg-primary text-black hover:bg-primary/90 mt-4 h-12">
              {isSubmitting ? 'Salvando...' : 'Entrar na Plataforma'}
            </Button>
            <p className="text-xs text-center text-zinc-500 mt-4 leading-relaxed">
              Você poderá editar as demais informações depois na página Meu Perfil.
            </p>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

