                            value={authEmail}
                            disabled
                            className="bg-zinc-800/50 border-zinc-700 h-12 text-white/50 cursor-not-allowed" 
                          />
                        </div>
                        <div>
                          <label className="text-sm text-zinc-400 mb-1.5 block font-medium">Senha</label>
