                        <FormField
                          control={contactForm.control}
                          name="email"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel className="text-gray-300">Email</FormLabel>
                              <FormControl>
                                <Input className="bg-zinc-900 border-zinc-700 text-white focus-visible:ring-primary" placeholder="seu@email.com" {...field} />
