'use client';

import { useState, useEffect } from 'react';
import { useUser } from '@/contexts/UserContext';
import { db } from '@/lib/firebase';
import { collection, query, where, getDocs, addDoc, updateDoc, deleteDoc, doc, serverTimestamp, Timestamp } from 'firebase/firestore';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { User, MessageSquare, Reply, Edit2, Trash2 } from 'lucide-react';

interface Comment {
  id: string;
  postId: string;
  userId: string;
  userName: string;
  userPhoto: string | null;
  text: string;
  isStudent: boolean;
  replyToId?: string | null;
  createdAt: Timestamp | null;
}

export function BlogComments({ slug }: { slug: string }) {
  const { user, loginWithGoogle } = useUser();
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  // Estados de Threading / Edição
  const [replyingToId, setReplyingToId] = useState<string | null>(null);
  const [replyText, setReplyText] = useState('');
  const [editingCommentId, setEditingCommentId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');

  useEffect(() => {
    fetchComments();
  }, [slug]);

  const fetchComments = async () => {
    try {
      const q = query(
        collection(db, 'blog_comments'), 
        where('postId', '==', slug)
      );
      
      const querySnapshot = await getDocs(q);
      const fetchedComments = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })) as Comment[];
      
      // Ordernar por mais antigos primeiro na base (depois invertemos os pais)
      fetchedComments.sort((a, b) => {
        const timeA = a.createdAt?.toMillis() || 0;
        const timeB = b.createdAt?.toMillis() || 0;
        return timeA - timeB; 
      });

      setComments(fetchedComments);
    } catch (error) {
      console.error('Erro ao buscar comentários:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user || !newComment.trim()) return;

    setIsSubmitting(true);
    try {
      await addDoc(collection(db, 'blog_comments'), {
        postId: slug,
        userId: user.uid,
        userName: user.displayName || 'Anônimo',
        userPhoto: user.photoURL || null,
        text: newComment.trim(),
        isStudent: !!user.hasCompletedOnboarding,
        replyToId: null,
        createdAt: serverTimestamp()
      });
      setNewComment('');
      fetchComments(); 
    } catch (error) {
      console.error('Erro ao salvar comentário:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleReply = async (parentId: string) => {
    if (!user || !replyText.trim()) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, 'blog_comments'), {
        postId: slug,
        userId: user.uid,
        userName: user.displayName || 'Anônimo',
        userPhoto: user.photoURL || null,
        text: replyText.trim(),
        isStudent: !!user.hasCompletedOnboarding,
        replyToId: parentId, // Vincula ao comentário pai
        createdAt: serverTimestamp()
      });
      setReplyText('');
      setReplyingToId(null);
      fetchComments(); 
    } catch (error) {
      console.error('Erro ao responder comentário:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEdit = async (commentId: string) => {
    if (!user || !editText.trim()) return;
    setIsSubmitting(true);
    try {
      const commentRef = doc(db, 'blog_comments', commentId);
      await updateDoc(commentRef, {
        text: editText.trim()
      });
      setEditingCommentId(null);
      setEditText('');
      fetchComments();
    } catch (error) {
      console.error('Erro ao editar comentário:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (commentId: string) => {
    if (!window.confirm('Tem certeza que deseja apagar este comentário?')) return;
    
    setIsSubmitting(true);
    try {
      // 1. Apaga as respostas que o usuário for dono no banco de dados (para limpar espaço)
      const replies = getReplies(commentId);
      for (const reply of replies) {
        if (reply.userId === user?.uid) {
          await deleteDoc(doc(db, 'blog_comments', reply.id));
        }
      }

      // 2. Apaga o comentário pai (Hard Delete)
      const commentRef = doc(db, 'blog_comments', commentId);
      await deleteDoc(commentRef);
      
      // Qualquer resposta de TERCEIROS que sobrar no banco ficará "órfã". 
      // Como o pai não existe mais, a UI automaticamente esconde essas respostas órfãs.
      fetchComments();
    } catch (error) {
      console.error('Erro ao deletar comentário:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Organizando as Threads: Pais e Filhos
  const parentComments = comments.filter(c => !c.replyToId).reverse(); // Mais novos no topo
  const getReplies = (parentId: string) => comments.filter(c => c.replyToId === parentId);

  const renderComment = (comment: Comment, isReply: boolean = false) => {
    const isOwner = user?.uid === comment.userId;
    const isEditing = editingCommentId === comment.id;
    const isReplying = replyingToId === comment.id;

    return (
      <div key={comment.id} className={`flex gap-4 ${isReply ? 'mt-6' : 'mt-8'}`}>
        {/* Avatar */}
        <div className="relative shrink-0">
          <div className={`w-10 h-10 md:w-12 md:h-12 rounded-full overflow-hidden bg-brand-graphite/20 relative z-10 ${
            comment.isStudent
              ? 'border-2 border-brand-gold shadow-[0_0_15px_rgba(238,187,46,0.6)]' 
              : ''
          }`}>
            {comment.userPhoto ? (
              <img src={comment.userPhoto} alt={comment.userName} className="w-full h-full object-cover" />
            ) : (
              <User className="w-full h-full p-2 text-brand-gray" />
            )}
          </div>
        </div>

        {/* Conteúdo */}
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-bold text-foreground">
              {comment.userName}
            </span>
            {comment.isStudent && (
              <span className="text-[10px] font-bold uppercase tracking-wider bg-brand-gold/20 text-brand-gold px-2 py-0.5 rounded-full shadow-[0_0_8px_rgba(238,187,46,0.3)]">
                Aluno
              </span>
            )}
            <span className="text-xs text-muted-foreground ml-2">
              {comment.createdAt?.toDate ? new Date(comment.createdAt.toDate()).toLocaleDateString('pt-BR') : 'Agora mesmo'}
            </span>
          </div>

          {/* Modo Edição vs Modo Visualização */}
          {isEditing ? (
            <div className="mt-2 space-y-2">
              <Input
                value={editText}
                onChange={(e) => setEditText(e.target.value)}
                className="w-full bg-card"
                autoFocus
              />
              <div className="flex gap-2">
                <Button 
                  size="sm" 
                  onClick={() => handleEdit(comment.id)} 
                  disabled={isSubmitting || !editText.trim()}
                  className="bg-brand-gold text-brand-black hover:bg-brand-gold/90 h-8"
                >
                  Salvar
                </Button>
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={() => setEditingCommentId(null)}
                  className="h-8"
                >
                  Cancelar
                </Button>
              </div>
            </div>
          ) : (
            <p className="font-body leading-relaxed whitespace-pre-wrap mt-1 text-muted-foreground">
              {comment.text}
            </p>
          )}

          {/* Ações (Apenas se logado) */}
          {user && !isEditing && (
            <div className="flex items-center gap-4 mt-2 text-xs font-bold">
              {!isReply && (
                <button 
                  onClick={() => { setReplyingToId(comment.id); setReplyText(''); }} 
                  className="flex items-center gap-1 text-muted-foreground hover:text-foreground transition-colors"
                >
                  <Reply className="w-3 h-3" /> Responder
                </button>
              )}
              {isOwner && (
                <>
                  <button 
                    onClick={() => { setEditingCommentId(comment.id); setEditText(comment.text); }} 
                    className="flex items-center gap-1 text-muted-foreground hover:text-brand-gold transition-colors"
                  >
                    <Edit2 className="w-3 h-3" /> Editar
                  </button>
                  <button 
                    onClick={() => handleDelete(comment.id)} 
                    className="flex items-center gap-1 text-muted-foreground hover:text-red-500 transition-colors"
                  >
                    <Trash2 className="w-3 h-3" /> Apagar
                  </button>
                </>
              )}
            </div>
          )}

          {/* Input de Resposta (Se ativo) */}
          {isReplying && !isReply && (
            <div className="mt-4 flex gap-3">
              <Input
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
                placeholder={`Respondendo a ${comment.userName}...`}
                className="w-full bg-card h-9 text-sm"
                autoFocus
              />
              <Button 
                size="sm" 
                onClick={() => handleReply(comment.id)} 
                disabled={isSubmitting || !replyText.trim()}
                className="bg-brand-gold text-brand-black hover:bg-brand-gold/90 h-9 shrink-0"
              >
                Enviar
              </Button>
              <Button 
                size="sm" 
                variant="ghost" 
                onClick={() => setReplyingToId(null)}
                className="h-9 shrink-0"
              >
                Cancelar
              </Button>
            </div>
          )}

          {/* Renderização dos Filhos (Respostas) */}
          {!isReply && getReplies(comment.id).length > 0 && (
            <div className="ml-4 md:ml-12 pl-4 border-l-2 border-border/50">
              {getReplies(comment.id).map(reply => renderComment(reply, true))}
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="mt-16 border-t border-border pt-12">
      <h3 className="text-2xl font-bold font-headline mb-8 flex items-center gap-2">
        <MessageSquare className="w-6 h-6 text-brand-gold" />
        Comentários ({comments.length})
      </h3>

      {/* Formulário Principal */}
      <div className="mb-12">
        {user ? (
          <form onSubmit={handleSubmit} className="flex gap-4 items-start">
            <div className="w-12 h-12 rounded-full overflow-hidden shrink-0 bg-brand-graphite/20 border-2 border-transparent">
              {user.photoURL ? (
                <img src={user.photoURL} alt={user.displayName || 'Você'} className="w-full h-full object-cover" />
              ) : (
                <User className="w-full h-full p-2 text-brand-gray" />
              )}
            </div>
            <div className="flex-1 space-y-2">
              <Input
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="Adicione um comentário à discussão..."
                className="w-full bg-card"
              />
              <div className="flex justify-end">
                <Button 
                  type="submit" 
                  disabled={isSubmitting || !newComment.trim()}
                  className="bg-brand-gold text-brand-black hover:bg-brand-gold/90 font-bold"
                >
                  {isSubmitting ? 'Enviando...' : 'Comentar'}
                </Button>
              </div>
            </div>
          </form>
        ) : (
          <div className="bg-card border border-border p-6 rounded-2xl text-center">
            <p className="text-muted-foreground mb-4 font-body">
              Junte-se à comunidade Nota Dentro para deixar o seu comentário.
            </p>
            <Button onClick={loginWithGoogle} className="bg-white text-black hover:bg-gray-100">
              Entrar com o Google
            </Button>
          </div>
        )}
      </div>

      {/* Lista de Comentários */}
      <div className="space-y-4">
        {isLoading ? (
          <p className="text-brand-gray italic">Carregando comentários...</p>
        ) : parentComments.length === 0 ? (
          <p className="text-brand-gray italic">Nenhum comentário ainda. Seja o primeiro!</p>
        ) : (
          parentComments.map(comment => renderComment(comment, false))
        )}
      </div>
    </div>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { Lesson } from '@/types/lesson';
import { TrailNode } from './TrailNode';
import { cn } from '@/lib/utils';

interface TrailMapProps {
  lessons: Lesson[];
  courseId: string;
  onLessonClick?: (lesson: Lesson) => void;
}

const Y_OFFSETS = [
  -30,  15, -10, // Row 0
  -10,  30,   0, // Row 1
    0, -20,  20, // Row 2
   20, -15, -30  // Row 3
];

export function TrailMap({ lessons, courseId, onLessonClick }: TrailMapProps) {
  const router = useRouter();
  
  // Divide lessons into chunks of 3 or 4 to create the "Staff Rows"
  const CHUNK_SIZE = 3;
  const rows: Lesson[][] = [];
  for (let i = 0; i < lessons.length; i += CHUNK_SIZE) {
    rows.push(lessons.slice(i, i + CHUNK_SIZE));
  }
  
  return (
    <div className="w-full max-w-4xl mx-auto flex flex-col gap-8 py-12 px-4 md:px-12 z-10">
      {rows.map((row, rowIndex) => {
        const nextRow = rows[rowIndex + 1];
        const isLastRow = rowIndex === rows.length - 1;
        return (
          <StaffRow 
            key={rowIndex} 
            lessons={row} 
            rowIndex={rowIndex} 
            router={router} 
            nextRowFirstNode={nextRow ? nextRow[0] : undefined}
            nextRowLength={nextRow ? nextRow.length : 0}
            nextRowOffset={nextRow ? Y_OFFSETS[((rowIndex + 1) * 3) % Y_OFFSETS.length] : 0}
            isLastRow={isLastRow}
            onLessonClick={onLessonClick}
            courseId={courseId}
          />
        );
      })}
    </div>
  );
}

interface StaffRowProps {
  lessons: Lesson[];
  rowIndex: number;
  router: any;
  nextRowFirstNode?: Lesson;
  nextRowLength?: number;
  nextRowOffset?: number;
  isLastRow?: boolean;
  onLessonClick?: (lesson: Lesson) => void;
  courseId: string;
}

function StaffRow({ lessons, rowIndex, router, nextRowFirstNode, nextRowLength, nextRowOffset, isLastRow, onLessonClick, courseId }: StaffRowProps) {
  // X coordinates for 896px width (max-w-4xl)
  const getXCoord = (index: number, total: number) => {
    return ((index * 2 + 1) / (total * 2)) * 896;
  };

  return (
    <div className="relative w-full h-[140px] flex items-center max-w-4xl mx-auto">
      
      {/* The 5 Lines of the Musical Staff with Barlines */}
      <div className="absolute left-0 right-0 h-[80px] flex flex-col justify-between z-0 pointer-events-none opacity-40">
        {/* Horizontal Lines */}
        {[...Array(5)].map((_, i) => (
          <div key={`line-${i}`} className="h-[2px] w-full bg-brand-white" />
        ))}
        
        {/* Barra Inicial */}
        <div className="absolute left-0 top-0 bottom-0 w-[2px] bg-brand-white" />

        {/* Barras de compasso intermediárias */}
        {[...Array(lessons.length - 1)].map((_, i) => {
          const leftPercent = ((i + 1) / lessons.length) * 100;
          return (
            <div 
              key={`barline-${i}`} 
              className="absolute top-0 bottom-0 w-[2px] bg-brand-white" 
              style={{ left: `${leftPercent}%` }}
            />
          );
        })}

        {/* Barra Final (Simples se continua, Dupla se for a última pauta) */}
        {isLastRow ? (
          <div className="absolute right-0 top-0 bottom-0 flex gap-1">
            <div className="w-[2px] bg-brand-white" />
            <div className="w-[6px] bg-brand-white" />
          </div>
        ) : (
          <div className="absolute right-0 top-0 bottom-0 w-[2px] bg-brand-white" />
        )}
      </div>

      {/* SVG Ligaduras (Connections) */}
      <svg 
        className="absolute inset-0 w-full h-full pointer-events-none z-0 overflow-visible"
        viewBox="0 0 896 140"
        preserveAspectRatio="none"
      >
        {lessons.map((lesson, i) => {
          const isLastInRow = i === lessons.length - 1;
          const nextLesson = isLastInRow ? nextRowFirstNode : lessons[i + 1];
          
          if (!nextLesson) return null; // Último nó do mapa inteiro
          
          const x1 = getXCoord(i, lessons.length);
          const y1 = 70 + Y_OFFSETS[(rowIndex * 3 + i) % Y_OFFSETS.length];
          const isGreen = lesson.status === 'completed';

          // Conexão entre pautas (Sheet Music style)
          if (isLastInRow) {
            const x2 = getXCoord(0, nextRowLength!);
            const y2 = 70 + 172 + nextRowOffset!; // 140 height + 32 gap = 172px de distância vertical
            
            const isCurrentRowTitleTop = rowIndex % 2 === 0;
            const dir1 = isCurrentRowTitleTop ? 1 : -1;
            
            const isNextRowTitleTop = (rowIndex + 1) % 2 === 0;
            const dir2 = isNextRowTitleTop ? 1 : -1;

            // Arco 1 sai reto na horizontal (endY = y1)
            const cy1 = y1 + (40 * dir1);
            const path1 = `M ${x1} ${y1} Q ${(x1 + 896)/2} ${cy1}, 896 ${y1}`;
            
            // Arco 2 chega reto da horizontal (startY = y2)
            const cy2 = y2 + (40 * dir2);
            const path2 = `M 0 ${y2} Q ${x2/2} ${cy2}, ${x2} ${y2}`;

            return (
              <g key={`line-inter-${rowIndex}`}>
                <path
                  d={path1}
                  fill="none"
                  stroke={isGreen ? "#2D8A5C" : "#4A4A4A"}
                  strokeWidth="4"
                  strokeLinecap="round"
                  className={cn("transition-colors duration-500", isGreen && "opacity-80")}
                />
                <path
                  d={path2}
                  fill="none"
                  stroke={isGreen ? "#2D8A5C" : "#4A4A4A"}
                  strokeWidth="4"
                  strokeLinecap="round"
                  className={cn("transition-colors duration-500", isGreen && "opacity-80")}
                />
              </g>
            );
          }

          // Conexão normal dentro da mesma pauta
          const x2 = getXCoord(i + 1, lessons.length);
          const y2 = 70 + Y_OFFSETS[(rowIndex * 3 + i + 1) % Y_OFFSETS.length];
          
          const cx = (x1 + x2) / 2;
          const curvesDown = rowIndex % 2 === 0;
          const cy = curvesDown ? Math.max(y1, y2) + 60 : Math.min(y1, y2) - 60; 

          return (
            <path
              key={`line-${i}`}
              d={`M ${x1} ${y1} Q ${cx} ${cy}, ${x2} ${y2}`}
              fill="none"
              stroke={isGreen ? "#2D8A5C" : "#4A4A4A"}
              strokeWidth="4"
              strokeLinecap="round"
              className={cn("transition-colors duration-500", isGreen && "opacity-80")}
            />
          );
        })}
      </svg>

      {/* The Nodes (Notes) */}
      <div className="relative z-10 w-full flex justify-around items-center h-full">
        {lessons.map((lesson, i) => {
          const offset = Y_OFFSETS[(rowIndex * 3 + i) % Y_OFFSETS.length];
          
          // Título sempre do lado oposto da curva da ligadura
          const titlePosition = rowIndex % 2 === 0 ? 'top' : 'bottom';
          
          return (
            <div 
              key={lesson.id} 
              className="relative flex items-center justify-center"
              style={{ transform: `translateY(${offset}px)` }}
            >
              <TrailNode 
                status={lesson.status}
                title={lesson.title}
                onClick={() => {
                  if (onLessonClick) {
                    onLessonClick(lesson);
                  } else {
                    router.push(`/lesson/${courseId}/${lesson.id}`);
                  }
                }}
                titlePosition={titlePosition}
              />
            </div>
          );
        })}
      </div>
      
    </div>
  );
}

import { motion } from 'framer-motion';
import { cn } from '@/lib/utils';
import { Crown, Lock, Play, Star } from 'lucide-react';
import { LessonStatus } from '@/types/lesson';

interface TrailNodeProps {
  status: LessonStatus;
  title: string;
  onClick?: () => void;
  isFirst?: boolean;
  titlePosition?: 'left' | 'right' | 'bottom' | 'top';
}

export function TrailNode({ status, title, onClick, isFirst, titlePosition = 'bottom' }: TrailNodeProps) {
  const isAvailable = status === 'available';
  const isCompleted = status === 'completed';
  const isLocked = status === 'locked';

  return (
    <div className="relative group flex flex-col items-center">
      {/* 3D Button Node */}
      <motion.button
        onClick={isLocked ? undefined : onClick}
        disabled={isLocked}
        whileHover={!isLocked ? { scale: 1.05 } : {}}
        whileTap={!isLocked ? { scale: 0.95, y: 4, boxShadow: "0 0px 0 0 transparent" } : {}}
        initial={isAvailable ? { scale: 0.9 } : {}}
        animate={isAvailable ? { 
          scale: [0.95, 1.05, 0.95],
        } : {}}
        transition={isAvailable ? {
          duration: 2,
          repeat: Infinity,
          ease: "easeInOut"
        } : {}}
        className={cn(
          "relative z-10 flex items-center justify-center rounded-full border-[3px] transition-colors duration-300",
          isAvailable ? "w-10 h-10 md:w-12 md:h-12 shadow-[0_4px_0_0_#A88A0D]" : "w-8 h-8 md:w-10 md:h-10",
          isCompleted && "bg-[#2D8A5C] border-[#2D8A5C] shadow-[0_3px_0_0_#1e5f3f] text-white",
          isAvailable && "bg-brand-gold border-brand-white dark:border-brand-black text-brand-black",
          isLocked && "bg-brand-sand dark:bg-brand-graphite border-brand-sand dark:border-brand-graphite shadow-[0_2px_0_0_#D1CFC7] dark:shadow-[0_2px_0_0_#2A2A2A] text-brand-gray cursor-not-allowed opacity-80"
        )}
      >
        {isCompleted && <Crown size={14} className="fill-white md:w-4 md:h-4" />}
        {isAvailable && <Star size={20} className="fill-brand-black md:w-6 md:h-6" />}
        {isLocked && <Lock size={12} className="md:w-3 md:h-3" />}
        
        {/* Glow effect for available node */}
        {isAvailable && (
          <div className="absolute -inset-4 bg-brand-gold/30 rounded-full blur-xl -z-10 animate-pulse" />
        )}
      </motion.button>
      
      {/* Permanent Title Beside or Below Node */}
      <div className={cn(
        "absolute w-max max-w-[120px] text-center text-xs md:text-sm font-bold bg-background/90 px-3 py-1.5 rounded-xl border border-brand-graphite/30 shadow-md leading-tight",
        isLocked ? "text-brand-gray" : "text-brand-white",
        titlePosition === 'bottom' && "top-[120%] mt-2",
        titlePosition === 'top' && "bottom-[120%] mb-2",
        titlePosition === 'left' && "right-[120%] top-1/2 -translate-y-1/2",
        titlePosition === 'right' && "left-[120%] top-1/2 -translate-y-1/2"
      )}>
        {title}
        
        {/* Bubble pointer */}
        {(titlePosition === 'left' || titlePosition === 'right') && (
          <div className={cn(
            "absolute top-1/2 -translate-y-1/2 w-2 h-2 rotate-45 bg-background border-brand-graphite/30",
            titlePosition === 'left' ? "-right-1 border-r border-t" : "-left-1 border-l border-b"
          )} />
        )}
      </div>
    </div>
  );
}

