'use client';

import React, { useState, useEffect, useRef } from 'react';
import { RhythmicReadingStep } from '@/types/lesson';
import { Button } from '@/components/ui/button';
import { Play, RefreshCw } from 'lucide-react';
import { cn } from '@/lib/utils';
import { MusicSymbol } from '@/components/music-symbols';

interface Props {
  data: RhythmicReadingStep;
  isCompleted: boolean;
  onSuccess: () => void;
  onFail: () => void;
}

type GameState = 'idle' | 'prep' | 'playing' | 'finished';
type BeatResult = 'perfect' | 'early' | 'late' | 'missed' | 'penalty' | null;

const scheduleClick = (ctx: AudioContext, freq: number, time: number) => {
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.connect(gain);
  gain.connect(ctx.destination);
  
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(freq, time);
  osc.frequency.exponentialRampToValueAtTime(freq * 0.2, time + 0.05);
  
  gain.gain.setValueAtTime(0, time);
  gain.gain.linearRampToValueAtTime(1, time + 0.002);
  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.05);
  
  osc.start(time);
  osc.stop(time + 0.05);
};

export function RhythmicReadingView({ data, isCompleted, onSuccess, onFail }: Props) {
  const { bpm = 65, sequence = [], toleranceMs = 200 } = data;
  const beatsToComplete = sequence.length;
  const beatMs = (60 / bpm) * 1000;

  const [status, setStatus] = useState<GameState>('idle');
  const [results, setResults] = useState<BeatResult[]>(Array(beatsToComplete).fill(null));
  const [elapsedTime, setElapsedTime] = useState(-4 * beatMs);
  const [score, setScore] = useState<number | null>(null);
  const [ghostMsg, setGhostMsg] = useState<{ text: string, id: number, type: BeatResult } | null>(null);
  const LATENCY_OFFSET_MS = 0.3; 

  const audioCtxRef = useRef<AudioContext | null>(null);
  const startTimeRef = useRef<number>(0);
  const animationRef = useRef<number>(0);
  const resultsRef = useRef<BeatResult[]>(Array(beatsToComplete).fill(null));
  const failTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const getCurrentTimeMs = () => {
    if (audioCtxRef.current && audioCtxRef.current.state === 'running') {
      return audioCtxRef.current.currentTime * 1000;
    }
    return performance.now();
  };

  useEffect(() => {
    resultsRef.current = results;
  }, [results]);

  useEffect(() => {
    return () => {
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, []);

  const showGhostMsg = (type: BeatResult) => {
    let msg = "Perfeito!";
    if (type === 'early') msg = "Adiantado";
    if (type === 'late') msg = "Atrasado";
    if (type === 'missed') msg = "Passou!";
    if (type === 'penalty') msg = "Aí é silêncio!";
    setGhostMsg({ text: msg, id: Date.now(), type });
  };

  const tick = () => {
    const elapsed = getCurrentTimeMs() - startTimeRef.current;
    setElapsedTime(elapsed);

    if (elapsed < 0) {
      animationRef.current = requestAnimationFrame(tick);
      return;
    }

    if (status === 'prep') {
      setStatus('playing');
    }

    const currentBeatIndex = Math.floor(elapsed / beatMs);
    const timeSinceBeat = elapsed - (currentBeatIndex * beatMs);

    if (currentBeatIndex >= 0 && currentBeatIndex < beatsToComplete) {
      if (timeSinceBeat > toleranceMs && resultsRef.current[currentBeatIndex] === null) {
        if (sequence[currentBeatIndex] === 'note') {
          // It was a note and we missed it
          setResults(prev => {
            const next = [...prev];
            next[currentBeatIndex] = 'missed';
            return next;
          });
          showGhostMsg('missed');
        } else if (sequence[currentBeatIndex] === 'rest' && currentBeatIndex < beatsToComplete) {
          // Passed a rest successfully without tapping!
          setResults(prev => {
            const next = [...prev];
            next[currentBeatIndex] = 'perfect';
            return next;
          });
          showGhostMsg('perfect');
        }
      }
    }

    if (currentBeatIndex >= beatsToComplete) {
      let finalHits = 0;
      let finalMisses = 0;
      let finalPenalties = 0;
      resultsRef.current.forEach((r, idx) => {
        if (sequence[idx] === 'rest' && r === 'penalty') finalPenalties++;
        else if (sequence[idx] === 'note') {
          if (r === 'perfect' || r === 'early' || r === 'late') finalHits++;
          if (r === 'missed') finalMisses++;
        }
      });

      const totalNotes = sequence.filter(s => s === 'note').length;
      let finalScore = totalNotes > 0 ? Math.round((finalHits / totalNotes) * 100) : 100;
      // Penalize for hitting rests
      finalScore -= finalPenalties * 15; 
      if (finalScore < 0) finalScore = 0;
      
      setScore(finalScore);
      setStatus('finished');

      if (finalScore >= 70) {
        setGhostMsg({ text: "Desafio Concluído!", id: Date.now(), type: 'perfect' });
        if (!isCompleted) onSuccess();
      } else {
        setGhostMsg({ text: "Tente novamente!", id: Date.now(), type: 'missed' });
        if (!isCompleted) onFail();
      }
      return;
    }

    animationRef.current = requestAnimationFrame(tick);
  };

  const startPrep = () => {
    if (failTimeoutRef.current) clearTimeout(failTimeoutRef.current);

    const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
    if (!audioCtxRef.current && AudioContext) {
      audioCtxRef.current = new AudioContext();
    }
    const ctx = audioCtxRef.current;
    if (ctx && ctx.state === 'suspended') ctx.resume();

    setStatus('prep');
    const freshResults = Array(beatsToComplete).fill(null);
    setResults(freshResults);
    resultsRef.current = freshResults;
    setScore(null);
    setGhostMsg(null);

    const nowTimeMs = getCurrentTimeMs();
    const beatSec = 60 / bpm;

    if (ctx) {
      // Metrônomo contínuo em toda a lição
      for (let i = 0; i < 4 + beatsToComplete; i++) {
        const freq = (i === 0) ? 1200 : 800;
        scheduleClick(ctx, freq, (nowTimeMs / 1000) + 0.1 + i * beatSec);
      }
    }

    startTimeRef.current = nowTimeMs + 100 + (4 * beatMs);

    if (animationRef.current) cancelAnimationFrame(animationRef.current);
    animationRef.current = requestAnimationFrame(tick);
  };

  const handleTap = () => {
    if (audioCtxRef.current) {
      scheduleClick(audioCtxRef.current, 400, audioCtxRef.current.currentTime);
    } else {
      const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
      if (AudioContext) {
        audioCtxRef.current = new AudioContext();
        scheduleClick(audioCtxRef.current, 400, audioCtxRef.current.currentTime);
      }
    }

    if (status === 'finished' || status === 'idle') return;

    const elapsed = getCurrentTimeMs() - startTimeRef.current - LATENCY_OFFSET_MS;
    if (status === 'prep' && elapsed < -toleranceMs) return;

    const closestBeat = Math.round(elapsed / beatMs);

    if (closestBeat >= 0 && closestBeat < beatsToComplete) {
      setResults(prev => {
        const next = [...prev];
        if (next[closestBeat] !== null) return prev; // Already registered

        const delta = elapsed - (closestBeat * beatMs);
        
        if (sequence[closestBeat] === 'rest') {
           // Tapped on a rest! Bad!
           if (Math.abs(delta) <= toleranceMs) {
             next[closestBeat] = 'penalty';
             showGhostMsg('penalty');
             return next;
           }
        } else {
          // Tapped on a note
          let type: BeatResult = 'perfect';
          if (Math.abs(delta) <= toleranceMs) {
            if (delta < -toleranceMs / 3) type = 'early';
            else if (delta > toleranceMs / 3) type = 'late';
            else type = 'perfect';
          } else {
            type = 'missed';
          }
          next[closestBeat] = type;
          showGhostMsg(type);
          return next;
        }
        return prev;
      });
    }
  };

  const handleTapRef = useRef(handleTap);
  useEffect(() => {
    handleTapRef.current = handleTap;
  }, [handleTap]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        e.preventDefault();
        handleTapRef.current();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const getResultColor = (r: BeatResult) => {
    switch (r) {
      case 'perfect': return 'text-green-500 border-green-500';
      case 'early': return 'text-yellow-500 border-yellow-500';
      case 'late': return 'text-orange-500 border-orange-500';
      case 'missed': return 'text-red-500 border-red-500';
      case 'penalty': return 'text-purple-500 border-purple-500'; // Touched a rest!
      default: return 'text-brand-gray/30 border-transparent';
    }
  };

  const getResultBg = (r: BeatResult) => {
    switch (r) {
      case 'perfect': return 'bg-green-500/20';
      case 'early': return 'bg-yellow-500/20';
      case 'late': return 'bg-orange-500/20';
      case 'missed': return 'bg-red-500/20';
      case 'penalty': return 'bg-purple-500/20';
      default: return 'bg-transparent';
    }
  };

  const visualBeatFloat = elapsedTime / beatMs;
  const totalDivisions = beatsToComplete + 4; // 4 prep beats + sequence

  return (
    <div className="flex flex-col items-center justify-center p-8 bg-brand-black min-h-[400px] font-body relative overflow-hidden select-none">
      
      {/* Ghost Message (Feedback de precisão) */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 h-10 flex items-center justify-center pointer-events-none z-50">
        {ghostMsg && (
          <div 
            key={ghostMsg.id} 
            className={cn(
              "font-headline text-3xl font-bold animate-ping-short drop-shadow-md",
              ghostMsg.type === 'perfect' ? 'text-green-400' :
              ghostMsg.type === 'penalty' ? 'text-purple-400' :
              ghostMsg.type === 'missed' ? 'text-red-400' : 'text-yellow-400'
            )}
          >
            {ghostMsg.text}
          </div>
        )}
      </div>

      <div className="flex flex-col items-center w-full max-w-4xl relative mt-10">
        
        {status === 'finished' && score !== null && (
          <div className="absolute inset-0 flex flex-col items-center justify-center z-40 bg-brand-black/90 backdrop-blur-sm rounded-xl">
            <h2 className="text-4xl font-headline font-bold text-brand-white mb-2">
              Precisão: <span className={score >= 70 ? 'text-green-400' : 'text-red-400'}>{score}%</span>
            </h2>
            {score >= 70 ? (
              <p className="text-green-300 font-bold mb-6">Leitura Rítmica Concluída!</p>
            ) : (
              <p className="text-red-300 font-bold mb-6">Não foi dessa vez...</p>
            )}
            
            <Button 
              onClick={startPrep}
              className={cn(
                "px-8 py-6 rounded-full text-brand-black text-xl font-bold shadow-lg mt-4",
                score >= 70 ? "bg-system-success hover:bg-green-600 text-white" : "bg-red-500 hover:bg-red-600 text-white"
              )}
            >
              <RefreshCw className="mr-2" /> {score >= 70 ? "Jogar Novamente" : "Tentar Novamente"}
            </Button>
          </div>
        )}

        {/* Pauta Horizontal */}
        <div className="w-full h-32 relative bg-brand-graphite/20 rounded-xl mb-12 flex items-center">
          
          {/* Cursor móvel */}
          {(status === 'prep' || status === 'playing') && (
            <div 
              className="absolute top-0 bottom-0 w-2 bg-brand-gold z-20 shadow-[0_0_15px_rgba(242,211,73,0.8)]"
              style={{
                left: `${((visualBeatFloat + 4) / totalDivisions) * 100}%`,
                transform: 'translateX(-50%)',
                transition: 'left 0.05s linear' // Suaviza a animação entre frames
              }}
            />
          )}

          {/* Renderiza as batidas preparatórias (-4 a -1) */}
          {[-4, -3, -2, -1].map((prepBeat) => {
             const leftPercent = ((prepBeat + 4) / totalDivisions) * 100;
             const isHovered = Math.abs(visualBeatFloat - prepBeat) < 0.2;
             return (
               <div 
                 key={`prep-${prepBeat}`}
                 className="absolute flex flex-col items-center"
                 style={{ left: `${leftPercent}%`, transform: 'translateX(-50%)' }}
               >
                 <div className={cn(
                   "w-4 h-4 rounded-full bg-brand-gray/40 transition-transform",
                   isHovered ? "scale-[1.8] bg-brand-gold" : ""
                 )} />
               </div>
             );
          })}

          {/* Renderiza a sequência da lição */}
          {sequence.map((item, idx) => {
            const leftPercent = ((idx + 4) / totalDivisions) * 100;
            const r = results[idx];
            const isHovered = Math.abs(visualBeatFloat - idx) < 0.2;

            return (
              <div 
                key={idx} 
                className="absolute flex flex-col items-center justify-center transition-all h-full"
                style={{ left: `${leftPercent}%`, transform: 'translateX(-50%)' }}
              >
                {/* Visual da figura musical */}
                <div className={cn(
                  "w-12 h-16 transition-all duration-100 flex items-center justify-center",
                  isHovered ? "-translate-y-2 scale-125" : ""
                )}>
                  {item === 'note' ? (
                    <img src="/assets/svg/seminima.svg" alt="Semínima" className="w-full h-full object-contain" />
                  ) : (
                    <img src="/assets/svg/pausa-seminima.svg" alt="Pausa de Semínima" className="w-full h-full object-contain" />
                  )}
                </div>
                
                {/* Base colorida após acerto/erro */}
                <div className={cn(
                  "w-12 h-2 mt-4 rounded-full border-2 transition-colors",
                  getResultBg(r),
                  getResultColor(r)
                )} />
              </div>
            );
          })}
        </div>

        <div className="flex flex-col items-center gap-6 w-full max-w-xs relative mt-4">
          {status === 'idle' ? (
            <Button 
              onClick={startPrep}
              className="w-full rounded-2xl py-6 bg-brand-gold hover:bg-yellow-400 text-brand-black text-xl font-bold shadow-lg shadow-brand-gold/30"
            >
              <Play className="mr-2" /> Começar
            </Button>
          ) : (
            <div className="h-[76px] w-full" />
          )}

          <div className="flex flex-col items-center gap-4 mt-2">
            <Button
              onPointerDown={(e) => { e.preventDefault(); handleTap(); }}
              className={cn(
                "w-28 h-28 rounded-full flex items-center justify-center transition-transform active:scale-90 p-0 overflow-hidden",
                status === 'playing' || status === 'prep' ? "bg-brand-gold hover:bg-yellow-400 shadow-lg shadow-brand-gold/30" : "bg-brand-graphite/20 text-brand-gray cursor-default"
              )}
            >
              <div className="w-full h-full p-2 flex items-center justify-center">
                <img 
                  src="/assets/svg/seminima.svg" 
                  alt="Tap" 
                  className="w-full h-full object-contain" 
                />
              </div>
            </Button>
            <span className="font-bold text-brand-gray text-lg">
              TAP <span className="hidden sm:inline">(Espaço)</span>
            </span>
          </div>
        </div>

      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { SandboxAudioStep } from '@/types/lesson';
import { Button } from '@/components/ui/button';
import { Play, Square, Check, Volume2, Activity } from 'lucide-react';
import { cn } from '@/lib/utils';

interface SandboxAudioViewProps {
  data: SandboxAudioStep;
  isCompleted: boolean;
  onSuccess: () => void;
}

export function SandboxAudioView({ data, isCompleted, onSuccess }: SandboxAudioViewProps) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [frequency, setFrequency] = useState(440); // A4
  const [gain, setGain] = useState(0.5);
  const [hasInteracted, setHasInteracted] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const oscillatorRef = useRef<OscillatorNode | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null);

  function stopAudio() {
    if (oscillatorRef.current && gainNodeRef.current && audioCtxRef.current) {
      const ct = audioCtxRef.current.currentTime;
      // Smooth release
      gainNodeRef.current.gain.cancelScheduledValues(ct);
      gainNodeRef.current.gain.setValueAtTime(gainNodeRef.current.gain.value, ct);
      gainNodeRef.current.gain.linearRampToValueAtTime(0, ct + 0.1);
      
      oscillatorRef.current.stop(ct + 0.1);
      
      oscillatorRef.current = null;
    }
    setIsPlaying(false);
  }

  useEffect(() => {
    // Cleanup on unmount
    return () => {
      stopAudio();
      if (audioCtxRef.current?.state !== 'closed') {
        audioCtxRef.current?.close();
      }
    };
  }, []);

  useEffect(() => {
    if (oscillatorRef.current) {
      // Usar exponentialRampToValueAtTime previne cliques abruptos e soa mais musical, 
      // mas como o slider muda a todo frame, setValueAtTime ou setTargetAtTime é melhor
      oscillatorRef.current.frequency.setTargetAtTime(frequency, audioCtxRef.current!.currentTime, 0.05);
    }
  }, [frequency]);

  useEffect(() => {
    if (gainNodeRef.current && audioCtxRef.current) {
      gainNodeRef.current.gain.setTargetAtTime(gain, audioCtxRef.current.currentTime, 0.05);
    }
  }, [gain]);

  const initAudio = () => {
    if (!audioCtxRef.current || audioCtxRef.current.state === 'closed') {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  };

  const playAudio = () => {
    initAudio();
    if (audioCtxRef.current?.state === 'suspended') {
      audioCtxRef.current.resume();
    }

    const osc = audioCtxRef.current!.createOscillator();
    const gainNode = audioCtxRef.current!.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(frequency, audioCtxRef.current!.currentTime);
    
    // Smooth attack
    gainNode.gain.setValueAtTime(0, audioCtxRef.current!.currentTime);
    gainNode.gain.linearRampToValueAtTime(gain, audioCtxRef.current!.currentTime + 0.1);

    osc.connect(gainNode);
    gainNode.connect(audioCtxRef.current!.destination);

    osc.start();

    oscillatorRef.current = osc;
    gainNodeRef.current = gainNode;
    
    setIsPlaying(true);
    setHasInteracted(true);
  };

;

  const toggleAudio = () => {
    if (isPlaying) {
      stopAudio();
    } else {
      playAudio();
    }
  };

  const handleComplete = () => {
    stopAudio();
    onSuccess();
  };

  return (
    <div className="flex flex-col gap-8 w-full max-w-3xl mx-auto items-center">
      <div className="text-center space-y-4">
        <p className="text-xl md:text-2xl font-medium text-inherit">
          {data.question}
        </p>
      </div>

      <div className="w-full bg-brand-graphite/5 border border-brand-graphite/20 p-8 rounded-3xl flex flex-col items-center gap-8 shadow-inner">
        
        {/* Play/Stop Button */}
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={toggleAudio}
          className={cn(
            "w-24 h-24 rounded-full flex items-center justify-center shadow-lg transition-colors border-4",
            isPlaying 
              ? "bg-red-500 hover:bg-red-600 text-white border-red-600 shadow-[0_0_30px_rgba(239,68,68,0.5)] animate-pulse" 
              : "bg-brand-gold hover:bg-yellow-500 text-brand-black border-yellow-600 shadow-[0_0_20px_rgba(242,211,73,0.3)]"
          )}
        >
          {isPlaying ? <Square size={36} fill="currentColor" /> : <Play size={40} className="ml-2" fill="currentColor" />}
        </motion.button>

        <div className="w-full space-y-8 mt-4">
          {/* Frequência (Altura) */}
          <div className="space-y-4">
            <div className="flex justify-between items-center text-inherit">
              <div className="flex items-center gap-2 font-bold text-lg">
                <Activity className="text-brand-gold" />
                <span>Altura (Frequência)</span>
              </div>
              <span className="font-mono bg-brand-black dark:bg-brand-white text-brand-white dark:text-brand-black px-3 py-1 rounded-lg text-sm">{frequency} Hz</span>
            </div>
            <input 
              type="range" 
              min="50" 
              max="2000" 
              step="1"
              value={frequency}
              onChange={(e) => setFrequency(Number(e.target.value))}
              className="w-full h-3 bg-brand-graphite/20 rounded-lg appearance-none cursor-pointer accent-brand-gold"
            />
            <div className="flex justify-between text-sm text-brand-gray font-medium">
              <span>Grave</span>
              <span>Agudo</span>
            </div>
          </div>

          {/* Intensidade (Volume) */}
          <div className="space-y-4">
            <div className="flex justify-between items-center text-inherit">
              <div className="flex items-center gap-2 font-bold text-lg">
                <Volume2 className="text-system-success" />
                <span>Intensidade (Volume)</span>
              </div>
              <span className="font-mono bg-brand-black dark:bg-brand-white text-brand-white dark:text-brand-black px-3 py-1 rounded-lg text-sm">{Math.round(gain * 100)}%</span>
            </div>
            <input 
              type="range" 
              min="0" 
              max="1" 
              step="0.01"
              value={gain}
              onChange={(e) => setGain(Number(e.target.value))}
              className="w-full h-3 bg-brand-graphite/20 rounded-lg appearance-none cursor-pointer accent-system-success"
            />
            <div className="flex justify-between text-sm text-brand-gray font-medium">
              <span>Piano (Fraco)</span>
              <span>Forte</span>
            </div>
          </div>
        </div>

      </div>

      <AnimatePresence>
        {isCompleted ? (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="p-6 bg-system-success/10 border border-system-success rounded-2xl w-full text-center"
          >
            <p className="font-bold text-system-success text-xl mb-2 flex items-center justify-center gap-2">
              <Check size={24} strokeWidth={3} /> Invenção Concluída!
            </p>
            <p className="text-inherit text-lg">{data.successMessage}</p>
          </motion.div>
        ) : (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: hasInteracted ? 1 : 0 }}
            className="w-full"
          >
            <Button 
              onClick={handleComplete} 
              disabled={!hasInteracted}
              className="w-full py-6 rounded-2xl font-bold text-lg bg-system-success hover:bg-green-600 text-white shadow-[0_4px_0_0_#1e5f3f] active:translate-y-1 active:shadow-none transition-all"
            >
              Concluir Invenção
            </Button>
          </motion.div>
        )}
      </AnimatePresence>

    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { motion, useAnimation, useDragControls } from 'framer-motion';
import { DragDropPautaStep } from '@/types/lesson';
import { CheckCircle2 } from 'lucide-react';

interface StaffDragDropViewProps {
  step: DragDropPautaStep;
  isCompleted: boolean;
  onSuccess: () => void;
}

export function StaffDragDropView({ step, isCompleted, onSuccess }: StaffDragDropViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [yPos, setYPos] = useState(160); // Inicia no segundo espaço para o aluno mover para o terceiro

  const targetMap: Record<string, number> = {
    'line-5': 60,
    'space-4': 80,
    'line-4': 100,
    'space-3': 120,
    'line-3': 140,
    'space-2': 160,
    'line-2': 180,
    'space-1': 200,
    'line-1': 220,
  };

  const handleDragEnd = (event: any, info: any) => {
    if (!containerRef.current || isCompleted) return;
    
    // info.offset.y é a distância percorrida no drag ATUAL
    const newY = yPos + info.offset.y; 
    
    let closestTarget = 'line-3';
    let minDiff = Infinity;
    let snapY = 140;
    
    Object.entries(targetMap).forEach(([target, y]) => {
      const diff = Math.abs(newY - y);
      if (diff < minDiff) {
        minDiff = diff;
        closestTarget = target;
        snapY = y;
      }
    });

    setYPos(snapY);

    if (closestTarget === step.expectedTarget) {
      onSuccess();
    }
  };

  return (
    <div className="flex flex-col items-center w-full max-w-2xl mx-auto space-y-6 bg-white p-6 md:p-8 rounded-3xl border-2 border-brand-graphite/10 shadow-sm">
      <h2 className="text-xl md:text-2xl font-bold font-headline text-center text-brand-black">
        {step.question}
      </h2>

      <div 
        ref={containerRef}
        className="relative w-full h-[300px] bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl overflow-hidden cursor-crosshair"
      >
        {/* Linhas da pauta renderizadas em HTML absoluto garantem 100% de precisão de pixels em qualquer tela */}
        {[60, 100, 140, 180, 220].map((y, i) => (
          <div key={`line-${i}`} className="absolute left-0 right-0 h-1 bg-slate-700" style={{ top: y - 2 }} />
        ))}

        <motion.div
          drag={!isCompleted}
          dragConstraints={containerRef}
          dragElastic={0.1}
          onDragEnd={handleDragEnd}
          animate={{ y: yPos }}
          transition={{ type: 'spring', stiffness: 300, damping: 20 }}
          whileHover={!isCompleted ? { scale: 1.1 } : {}}
          whileDrag={!isCompleted ? { scale: 1.2, cursor: 'grabbing' } : {}}
          className="absolute z-10 w-11 h-8 cursor-grab left-1/2 -translate-x-1/2"
          style={{ top: 0, marginTop: -16 }} // marginTop ajusta perfeitamente o centro do corpo da nota para o yPos
        >
          {/* Haste (Stem) */}
          <div className="absolute right-0 bottom-3 w-1 h-14 bg-brand-black rounded-t-full" />
          
          {/* Corpo da nota (Notehead) */}
          <div className="absolute inset-0 bg-brand-gold rounded-[50%] border-4 border-brand-black shadow-sm -rotate-[20deg]" />
        </motion.div>
      </div>

      {isCompleted && (
        <motion.div 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-emerald-100 text-emerald-800 p-4 rounded-xl flex items-start gap-3 w-full"
        >
          <CheckCircle2 className="w-6 h-6 shrink-0 text-emerald-600" />
          <p className="font-bold">{step.successMessage}</p>
        </motion.div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Lesson, QuizStep, TheoryStep, TrueFalseStep, MatchColumnsStep, MemoryGameStep, FillBlanksStep } from '@/types/lesson';
import { Progress } from '@/components/ui/progress';
import { X, Check, AlertCircle, Volume2, ThumbsUp, ThumbsDown } from 'lucide-react';
import { MatchColumns } from './exercises/MatchColumns';
import { MemoryGame } from './exercises/MemoryGame';
import { FillBlanks } from './exercises/FillBlanks';
import { cn } from '@/lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import confetti from 'canvas-confetti';
import { useUser } from '@/contexts/UserContext';
import { useRef } from 'react';

interface LessonEngineProps {
  lesson: Lesson;
}

export function LessonEngine({ lesson }: LessonEngineProps) {
  const router = useRouter();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isChecking, setIsChecking] = useState(false);
  const [isCorrect, setIsCorrect] = useState<boolean | null>(null);
  const { addXP } = useUser();
  const hasAwardedXP = useRef(false);

  const steps = lesson.steps;
  const isFinished = currentIndex >= steps.length;
  const progress = isFinished ? 100 : (currentIndex / steps.length) * 100;

  useEffect(() => {
    if (isFinished) {
      if (!hasAwardedXP.current) {
        addXP(50); // Provide 50 XP per lesson completion
        hasAwardedXP.current = true;
      }
      // Golden fireworks!
      const duration = 3 * 1000;
      const animationEnd = Date.now() + duration;
      const defaults = { startVelocity: 45, spread: 360, ticks: 60, zIndex: 100, colors: ['#C9A811', '#EDD033', '#A88A0D', '#F8F6F0', '#E8E6DF'] };

      const randomInRange = (min: number, max: number) => Math.random() * (max - min) + min;

      const interval: any = setInterval(function() {
        const timeLeft = animationEnd - Date.now();

        if (timeLeft <= 0) {
          return clearInterval(interval);
        }

        const particleCount = 40 * (timeLeft / duration);
        // Fireworks from the sides
        confetti({ ...defaults, particleCount, origin: { x: randomInRange(0.1, 0.3), y: Math.random() - 0.2 } });
        confetti({ ...defaults, particleCount, origin: { x: randomInRange(0.7, 0.9), y: Math.random() - 0.2 } });
      }, 250);

      // Huge burst from bottom center
      confetti({
        particleCount: 150,
        spread: 120,
        origin: { y: 0.9 },
        colors: ['#C9A811', '#EDD033', '#A88A0D', '#F8F6F0'],
        startVelocity: 80, // shoot up high!
        zIndex: 100,
      });

      return () => clearInterval(interval);
    }
  }, [isFinished]);

  if (steps.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-screen p-4 text-center">
        <h2 className="text-2xl font-headline mb-4">Lição em Construção</h2>
        <button 
          onClick={() => router.push('/dashboard')}
          className="px-6 py-3 bg-brand-gold text-brand-black font-bold rounded-xl shadow-[0_4px_0_0_#A88A0D] hover:translate-y-[2px] hover:shadow-[0_2px_0_0_#A88A0D] active:translate-y-[4px] active:shadow-none transition-all"
        >
          Voltar
        </button>
      </div>
    );
  }

  if (isFinished) {
    return (
      <div className="flex flex-col items-center justify-center h-screen p-4 text-center bg-brand-white dark:bg-brand-black overflow-hidden relative">
        <motion.div 
          initial={{ scale: 0, rotate: -180 }}
          animate={{ scale: 1, rotate: 0 }}
          transition={{ type: 'spring', bounce: 0.5, duration: 0.8 }}
          className="w-32 h-32 bg-system-success/20 rounded-full flex items-center justify-center mb-6 text-system-success"
        >
          <Check size={80} strokeWidth={3} />
        </motion.div>
        
        <motion.h2 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="text-4xl md:text-5xl font-headline font-extrabold text-brand-gold mb-4"
        >
          Lição Concluída!
        </motion.h2>
        
        <motion.p 
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          className="text-xl text-brand-gray mb-12 font-medium"
        >
          Você mandou super bem e ganhou <span className="text-brand-gold font-bold">+10 XP</span>!
        </motion.p>
        
        <motion.button 
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.7, type: 'spring' }}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className="w-full max-w-sm bg-brand-gold text-brand-black font-extrabold text-xl py-4 rounded-2xl shadow-[0_6px_0_0_#A88A0D] hover:translate-y-[2px] hover:shadow-[0_4px_0_0_#A88A0D] active:translate-y-[6px] active:shadow-none transition-all uppercase tracking-wide"
          onClick={() => router.push('/dashboard')}
        >
          Continuar
        </motion.button>
      </div>
    );
  }

  const currentStep = steps[currentIndex];
  const isMultipleChoice = currentStep.type === 'quiz';
  const isTrueFalse = currentStep.type === 'true_false';
  const isMatchColumns = currentStep.type === 'match_columns';
  const isMemoryGame = currentStep.type === 'memory_game';
  const isFillBlanks = currentStep.type === 'fill_blanks';
  
  const isInteractive = isMultipleChoice || isTrueFalse; // Require explicit "Verify" click
  const isAdvancedGame = isMatchColumns || isMemoryGame || isFillBlanks; // Self-verifying
  
  const quizData = isMultipleChoice ? (currentStep.data as QuizStep) : null;
  const trueFalseData = isTrueFalse ? (currentStep.data as TrueFalseStep) : null;
  const matchColumnsData = isMatchColumns ? (currentStep.data as MatchColumnsStep) : null;
  const memoryGameData = isMemoryGame ? (currentStep.data as MemoryGameStep) : null;
  const fillBlanksData = isFillBlanks ? (currentStep.data as FillBlanksStep) : null;
  const theoryData = currentStep.type === 'theory' ? (currentStep.data as TheoryStep) : null;

  const handleNext = () => {
    if (isInteractive && !isChecking) {
      if (!selectedOption) return;
      
      let correct = false;
      if (isMultipleChoice) {
        correct = selectedOption === quizData?.correctAnswer;
      } else if (isTrueFalse) {
        correct = selectedOption === (trueFalseData?.isTrue ? 'true' : 'false');
      }
      
      setIsCorrect(correct);
      setIsChecking(true);
      return;
    }

    // Next step
    setSelectedOption(null);
    setIsChecking(false);
    setIsCorrect(null);
    setCurrentIndex((prev) => prev + 1);
  };

  const handleAdvancedGameComplete = (correct: boolean) => {
    if (correct) {
      setIsCorrect(true);
      setIsChecking(true);
    }
  };

  // 3D Button style helper
  const getOptionStyle = (option: string) => {
    const isSelected = selectedOption === option;
    
    let isCorrectOption = false;
    if (isMultipleChoice) isCorrectOption = isChecking && option === quizData?.correctAnswer;
    if (isTrueFalse) isCorrectOption = isChecking && option === (trueFalseData?.isTrue ? 'true' : 'false');
    
    const isWrongSelected = isChecking && isSelected && !isCorrect;

    if (isCorrectOption) {
      return "border-system-success bg-system-success/10 text-system-success shadow-[0_4px_0_0_#2D8A5C] translate-y-[-2px]";
    }
    if (isWrongSelected) {
      return "border-system-error bg-system-error/10 text-system-error shadow-[0_4px_0_0_#C0392B] translate-y-[-2px] opacity-70";
    }
    if (isSelected && !isChecking) {
      return "border-brand-gold bg-brand-gold/10 text-brand-gold shadow-[0_4px_0_0_#C9A811] translate-y-[-2px]";
    }
    
    // Default
    return "border-brand-sand dark:border-brand-graphite bg-transparent text-brand-black dark:text-brand-white shadow-[0_4px_0_0_#E8E6DF] dark:shadow-[0_4px_0_0_#3A3A3A] hover:bg-brand-sand/30 dark:hover:bg-brand-graphite/30 translate-y-[-2px]";
  };

  return (
    <div className="flex flex-col min-h-[100dvh] bg-brand-white dark:bg-brand-black font-body selection:bg-brand-gold/30 pb-48">
      
      {/* HEADER */}
      <header className="sticky top-0 z-40 bg-brand-white dark:bg-brand-black flex items-center gap-3 md:gap-4 p-4 md:p-6 max-w-4xl mx-auto w-full">
        <button 
          onClick={() => router.push('/dashboard')} 
          className="text-brand-gray hover:text-brand-black dark:hover:text-brand-white transition-colors"
        >
          <X size={28} className="md:w-[32px] md:h-[32px]" strokeWidth={2.5} />
        </button>
        <div className="flex-1 relative h-4 overflow-hidden rounded-full">
          <Progress value={progress} className="h-full bg-brand-sand dark:bg-brand-graphite [&>div]:bg-system-success shadow-inner" />
          
          {/* Wrapper to clip the shine exactly to the current progress */}
          <div 
            className="absolute top-0 left-0 bottom-0 overflow-hidden rounded-full pointer-events-none transition-all duration-300"
            style={{ width: `${progress}%` }}
          >
            {/* Animated Sweep (Shine) Effect - Gold */}
            <div 
              className="absolute top-0 bottom-0 w-24 bg-gradient-to-r from-transparent via-brand-gold/80 to-transparent skew-x-[-20deg] animate-sweep"
            />
          </div>
        </div>
      </header>

      {/* CONTENT AREA */}
      <main className="flex-1 flex flex-col max-w-3xl mx-auto w-full px-4 md:px-6 py-4 relative">
        <AnimatePresence mode="wait">
          <motion.div
            key={currentIndex}
            initial={{ x: 50, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: -50, opacity: 0 }}
            transition={{ type: 'spring', stiffness: 300, damping: 25 }}
            className="flex-1 flex flex-col justify-center min-h-[50vh]"
          >
            
            <h2 className="text-2xl md:text-4xl font-headline font-extrabold mb-6 md:mb-8 text-brand-black dark:text-brand-white leading-tight">
              {currentStep.title}
            </h2>

            {/* THEORY STEP */}
            {theoryData && (
              <div className="flex flex-col gap-6 md:gap-8">
                <div className="p-5 md:p-8 bg-brand-sand/30 dark:bg-brand-graphite/30 rounded-2xl md:rounded-3xl border-2 border-brand-sand dark:border-brand-graphite relative overflow-hidden">
                  
                  {/* Decorative Icon */}
                  <div className="absolute -top-4 -right-4 text-brand-gold/10 pointer-events-none">
                    <MusicIcon size={100} className="md:w-[120px] md:h-[120px]" />
                  </div>

                  <p className="text-lg md:text-2xl leading-relaxed text-brand-black dark:text-brand-white relative z-10">
                    {theoryData.content.split('**').map((text, i) => 
                      i % 2 === 1 ? <span key={i} className="text-brand-gold font-bold">{text}</span> : text
                    )}
                  </p>
                </div>

                {/* Optional Audio/Image feature ready for the future */}
                <div className="flex justify-center mt-2">
                  <motion.button 
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    className="flex items-center gap-2 px-6 py-3 rounded-full bg-brand-gold/20 text-brand-gold font-bold text-lg cursor-not-allowed opacity-50"
                    title="Em breve!"
                  >
                    <Volume2 size={24} /> Ouvir Exemplo
                  </motion.button>
                </div>
              </div>
            )}

            {/* QUIZ STEP */}
            {quizData && (
              <div className="flex flex-col gap-6 md:gap-8 w-full">
                <p className="text-2xl md:text-3xl font-bold text-brand-black dark:text-brand-white leading-snug">
                  {quizData.question}
                </p>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {quizData.options.map((option, idx) => {
                    const isActive = selectedOption === option;
                    
                    return (
                      <motion.button
                        key={option}
                        disabled={isChecking}
                        onClick={() => setSelectedOption(option)}
                        whileHover={!isChecking && !isActive ? { y: -4 } : {}}
                        whileTap={!isChecking ? { y: 2, boxShadow: "0 0px 0 0 transparent" } : {}}
                        className={cn(
                          "relative p-5 rounded-2xl border-2 text-left font-bold text-lg md:text-xl transition-colors duration-200",
                          getOptionStyle(option)
                        )}
                      >
                        {option}
                      </motion.button>
                    );
                  })}
                </div>
              </div>
            )}

            {/* TRUE / FALSE STEP */}
            {trueFalseData && (
              <div className="flex flex-col gap-6 md:gap-8 w-full">
                <p className="text-2xl md:text-3xl font-bold text-brand-black dark:text-brand-white leading-snug">
                  {trueFalseData.statement}
                </p>
                
                <div className="grid grid-cols-2 gap-4 md:gap-6 mt-4">
                  <motion.button
                    disabled={isChecking}
                    onClick={() => setSelectedOption('true')}
                    whileHover={!isChecking && selectedOption !== 'true' ? { y: -4 } : {}}
                    whileTap={!isChecking ? { y: 2, boxShadow: "0 0px 0 0 transparent" } : {}}
                    className={cn(
                      "flex flex-col items-center justify-center gap-4 py-8 md:py-12 rounded-3xl border-2 font-bold text-xl md:text-2xl transition-colors duration-200",
                      getOptionStyle('true')
                    )}
                  >
                    <div className={cn(
                      "p-4 rounded-full border-2",
                      selectedOption === 'true' && !isChecking ? "border-brand-gold bg-brand-gold/20" : 
                      isChecking && trueFalseData.isTrue ? "border-system-success bg-system-success/20" : 
                      isChecking && !trueFalseData.isTrue && selectedOption === 'true' ? "border-system-error bg-system-error/20" :
                      "border-brand-sand dark:border-brand-graphite bg-brand-sand/10 dark:bg-brand-graphite/10"
                    )}>
                      <ThumbsUp size={48} strokeWidth={2.5} />
                    </div>
                    Verdadeiro
                  </motion.button>

                  <motion.button
                    disabled={isChecking}
                    onClick={() => setSelectedOption('false')}
                    whileHover={!isChecking && selectedOption !== 'false' ? { y: -4 } : {}}
                    whileTap={!isChecking ? { y: 2, boxShadow: "0 0px 0 0 transparent" } : {}}
                    className={cn(
                      "flex flex-col items-center justify-center gap-4 py-8 md:py-12 rounded-3xl border-2 font-bold text-xl md:text-2xl transition-colors duration-200",
                      getOptionStyle('false')
                    )}
                  >
                    <div className={cn(
                      "p-4 rounded-full border-2",
                      selectedOption === 'false' && !isChecking ? "border-brand-gold bg-brand-gold/20" : 
                      isChecking && !trueFalseData.isTrue ? "border-system-success bg-system-success/20" : 
                      isChecking && trueFalseData.isTrue && selectedOption === 'false' ? "border-system-error bg-system-error/20" :
                      "border-brand-sand dark:border-brand-graphite bg-brand-sand/10 dark:bg-brand-graphite/10"
                    )}>
                      <ThumbsDown size={48} strokeWidth={2.5} />
                    </div>
                    Falso
                  </motion.button>
                </div>
              </div>
            )}

            {/* ADVANCED EXERCISES */}
            {isMatchColumns && matchColumnsData && (
              <MatchColumns data={matchColumnsData} onComplete={handleAdvancedGameComplete} />
            )}
            
            {isMemoryGame && memoryGameData && (
              <MemoryGame data={memoryGameData} onComplete={handleAdvancedGameComplete} />
            )}
            
            {isFillBlanks && fillBlanksData && (
              <FillBlanks data={fillBlanksData} onComplete={handleAdvancedGameComplete} />
            )}

          </motion.div>
        </AnimatePresence>
      </main>

      {/* BOTTOM FOOTER (Action & Feedback) */}
      <motion.footer 
        layout
        className={cn(
          "fixed bottom-0 left-0 right-0 z-50 border-t-2 px-6 py-4 md:py-6 transition-colors duration-300",
          !isChecking ? "bg-brand-white dark:bg-brand-black border-brand-sand dark:border-brand-graphite" : 
          isCorrect ? "bg-[#F0FAF5] dark:bg-system-success/15 border-system-success" : "bg-[#FDF4F4] dark:bg-system-error/15 border-system-error"
        )}
      >
        <div className="max-w-4xl mx-auto w-full flex flex-col gap-4 md:gap-6">
          
          {/* Feedback Content (Only rendered when checking) */}
          <AnimatePresence>
            {isChecking && (
              <motion.div 
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="flex items-start gap-4 overflow-hidden"
              >
                <motion.div 
                  initial={{ scale: 0.5 }}
                  animate={{ scale: 1 }}
                  transition={{ type: "spring", bounce: 0.6, delay: 0.1 }}
                  className={cn(
                    "p-3 rounded-full flex-shrink-0 mt-1",
                    isCorrect ? "bg-system-success text-white" : "bg-system-error text-white"
                  )}
                >
                  {isCorrect ? <Check size={32} strokeWidth={3} /> : <X size={32} strokeWidth={3} />}
                </motion.div>

                <div className="flex flex-col gap-1">
                  <h3 className={cn(
                    "font-headline font-extrabold text-2xl md:text-3xl",
                    isCorrect ? "text-system-success" : "text-system-error"
                  )}>
                    {isCorrect ? 'Você acertou!' : 'Quase lá!'}
                  </h3>
                  <p className={cn(
                    "text-base md:text-lg font-medium",
                    isCorrect ? "text-system-success/80" : "text-system-error/80"
                  )}>
                    {isMultipleChoice ? quizData?.explanation : 
                     isTrueFalse ? trueFalseData?.explanation : 
                     isMatchColumns ? matchColumnsData?.explanation : 
                     isMemoryGame ? memoryGameData?.explanation : 
                     isFillBlanks ? fillBlanksData?.explanation : ''}
                  </p>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Action Button */}
          <div className="flex w-full justify-end">
            <button 
              disabled={(isInteractive && !selectedOption && !isChecking) || (isAdvancedGame && !isChecking)}
              onClick={handleNext}
              className={cn(
                "w-full md:w-auto min-w-[200px] font-extrabold text-xl py-4 px-8 rounded-2xl uppercase tracking-wider transition-all",
                (!isInteractive || selectedOption) && !isChecking && !isAdvancedGame ? "bg-brand-gold text-brand-black shadow-[0_6px_0_0_#A88A0D] hover:translate-y-[2px] hover:shadow-[0_4px_0_0_#A88A0D] active:translate-y-[6px] active:shadow-none" : "",
                (isInteractive && !selectedOption && !isChecking) || (isAdvancedGame && !isChecking) ? "bg-brand-sand dark:bg-brand-graphite text-brand-gray cursor-not-allowed shadow-[0_6px_0_0_#D1CFC7] dark:shadow-[0_6px_0_0_#2A2A2A]" : "",
                isChecking && isCorrect ? "bg-system-success text-white shadow-[0_6px_0_0_#1E6240] hover:translate-y-[2px] hover:shadow-[0_4px_0_0_#1E6240] active:translate-y-[6px] active:shadow-none" : "",
                isChecking && !isCorrect ? "bg-system-error text-white shadow-[0_6px_0_0_#962D22] hover:translate-y-[2px] hover:shadow-[0_4px_0_0_#962D22] active:translate-y-[6px] active:shadow-none" : ""
              )}
            >
              {isChecking ? 'Continuar' : 'Verificar'}
            </button>
          </div>
        </div>
      </motion.footer>
    </div>
  );
}

// Simple decorative icon component for the theory card
function MusicIcon(props: any) {
  return (
    <svg
      {...props}
      xmlns="http://www.w3.org/2000/svg"
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M9 18V5l12-2v13" />
      <circle cx="6" cy="18" r="3" />
      <circle cx="18" cy="16" r="3" />
    </svg>
  );
}

